import{_ as o,o as t,c as a,a6 as n}from"./chunks/framework.BrkgobfX.js";const p=JSON.parse('{"title":"状态码：1xx 与 2xx","description":"状态码注册规则、可缓存码集合，以及信息性与成功类每个码的精确触发条件。","frontmatter":{"title":"状态码：1xx 与 2xx","description":"状态码注册规则、可缓存码集合，以及信息性与成功类每个码的精确触发条件。","source":"https://daiw.org/manual/http11/status-codes"},"headers":[],"relativePath":"manual/computer-programming/http11/status-codes.md","filePath":"manual/computer-programming/http11/status-codes.md"}'),r={name:"manual/computer-programming/http11/status-codes.md"};function c(i,e,d,l,s,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="状态码-1xx-与-2xx" tabindex="-1">状态码：1xx 与 2xx <a class="header-anchor" href="#状态码-1xx-与-2xx" aria-label="Permalink to &quot;状态码：1xx 与 2xx&quot;">​</a></h1><h2 id="注册与扩展规则" tabindex="-1">注册与扩展规则 <a class="header-anchor" href="#注册与扩展规则" aria-label="Permalink to &quot;注册与扩展规则&quot;">​</a></h2><p>状态码是<strong>三位数字</strong>，首位定类别。核心码由 RFC 9110 定义，其余散见于 WebDAV（RFC 4918）等扩展并登记在 IANA 注册表。</p><p>三条硬规则：</p><ol><li>客户端 <strong>MUST</strong> 理解类别，<strong>不必</strong>理解具体码；不认识的码按该类别的 <code>x00</code> 处理（见<a href="/Front2Full/manual/computer-programming/http11/status-line">状态行</a>）。</li><li>缓存 <strong>MUST NOT</strong> 缓存不认识的状态码的响应，除非有显式的 <code>Cache-Control</code> 允许。</li><li>新增状态码<strong>不得</strong>要求客户端改造——这正是规则 1 存在的原因。</li></ol><h2 id="默认可缓存的状态码" tabindex="-1">默认可缓存的状态码 <a class="header-anchor" href="#默认可缓存的状态码" aria-label="Permalink to &quot;默认可缓存的状态码&quot;">​</a></h2><p>以下码的响应在<strong>无显式缓存指令时</strong>也可被缓存（「heuristically cacheable」）：</p><p><code>200</code>、<code>203</code>、<code>204</code>、<code>206</code>、<code>300</code>、<code>301</code>、<code>308</code>、<code>404</code>、<code>405</code>、<code>410</code>、<code>414</code>、<code>501</code></p><p>其余状态码<strong>必须</strong>有显式 <code>Cache-Control</code>/<code>Expires</code> 才可存储。注意 <code>404</code>、<code>410</code> 在列——这是「删掉的页面仍返回旧 404」的常见成因，必要时用 <code>Cache-Control: no-store</code> 覆盖。</p><h2 id="_1xx-信息性" tabindex="-1">1xx：信息性 <a class="header-anchor" href="#_1xx-信息性" aria-label="Permalink to &quot;1xx：信息性&quot;">​</a></h2><p><strong>中间响应</strong>，其后必有最终响应。恒无消息体，<strong>MUST NOT</strong> 发给 HTTP/1.0 客户端。</p><h3 id="_100-continue" tabindex="-1">100 Continue <a class="header-anchor" href="#_100-continue" aria-label="Permalink to &quot;100 Continue&quot;">​</a></h3><p>服务端愿意接收请求体，客户端应继续发送。仅在客户端发了 <code>Expect: 100-continue</code> 时产生。</p><ul><li>服务端已开始读取请求体后 <strong>MUST NOT</strong> 再发 <code>100</code>。</li><li>客户端超时未收到时可直接发体，不算错误。</li><li>详见 <a href="/Front2Full/manual/computer-programming/http11/connection-management">Expect 与 100-continue</a>。</li></ul><h3 id="_101-switching-protocols" tabindex="-1">101 Switching Protocols <a class="header-anchor" href="#_101-switching-protocols" aria-label="Permalink to &quot;101 Switching Protocols&quot;">​</a></h3><p>服务端同意按 <code>Upgrade</code> 切换协议，<strong>MUST</strong> 带 <code>Upgrade</code> 字段指明切到什么。响应结束后连接按新协议解释。WebSocket 握手的标准响应码。</p><h3 id="_102-processing" tabindex="-1">102 Processing <a class="header-anchor" href="#_102-processing" aria-label="Permalink to &quot;102 Processing&quot;">​</a></h3><p>WebDAV（RFC 2518）。表示「仍在处理，别超时」。已在 RFC 4918 中被移除，不应新用。</p><h3 id="_103-early-hints" tabindex="-1">103 Early Hints <a class="header-anchor" href="#_103-early-hints" aria-label="Permalink to &quot;103 Early Hints&quot;">​</a></h3><p>RFC 8297。在最终响应前先发 <code>Link</code> 等提示，让客户端提前预加载资源。</p><ul><li>只携带<strong>提示性</strong>头字段，客户端 <strong>MUST NOT</strong> 把它当最终响应的头。</li><li>最终响应可能与提示不一致（如实际返回 <code>404</code>），客户端需容忍。</li></ul><h2 id="_2xx-成功" tabindex="-1">2xx：成功 <a class="header-anchor" href="#_2xx-成功" aria-label="Permalink to &quot;2xx：成功&quot;">​</a></h2><h3 id="_200-ok" tabindex="-1">200 OK <a class="header-anchor" href="#_200-ok" aria-label="Permalink to &quot;200 OK&quot;">​</a></h3><p>请求成功，语义随方法而异：<code>GET</code> 返回资源表示、<code>POST</code> 返回处理结果、<code>PUT</code>/<code>DELETE</code> 返回状态描述。默认可缓存。</p><h3 id="_201-created" tabindex="-1">201 Created <a class="header-anchor" href="#_201-created" aria-label="Permalink to &quot;201 Created&quot;">​</a></h3><p>已新建一个或多个资源。</p><ul><li><strong>SHOULD</strong> 带 <code>Location</code> 指向主要新资源；无 <code>Location</code> 时以请求 URI 为准。</li><li>响应中的验证器字段（<code>ETag</code>、<code>Last-Modified</code>）描述的是<strong>新建资源</strong>的表示。</li></ul><h3 id="_202-accepted" tabindex="-1">202 Accepted <a class="header-anchor" href="#_202-accepted" aria-label="Permalink to &quot;202 Accepted&quot;">​</a></h3><p>已受理但<strong>未完成</strong>，且不保证最终完成。用于异步处理。</p><ul><li>响应体应说明当前状态与查询进度的方式（如带轮询 URI）。</li><li>这是「故意不承诺」的码——不能用它表示「已成功」。</li></ul><h3 id="_203-non-authoritative-information" tabindex="-1">203 Non-Authoritative Information <a class="header-anchor" href="#_203-non-authoritative-information" aria-label="Permalink to &quot;203 Non-Authoritative Information&quot;">​</a></h3><p><code>200</code> 的变体：返回的载荷被<strong>中间代理修改过</strong>（如转码、注入），不再来自源服务器。默认可缓存。极少使用。</p><h3 id="_204-no-content" tabindex="-1">204 No Content <a class="header-anchor" href="#_204-no-content" aria-label="Permalink to &quot;204 No Content&quot;">​</a></h3><p>成功，且<strong>无消息体</strong>（恒无，见成帧规则）。</p><ul><li>可带验证器（<code>ETag</code>）表示新状态。</li><li>语义：「已完成，页面不必跳转、不必刷新」。表单提交与 <code>DELETE</code> 常用。</li><li>与 <code>205</code> 的区别：<code>204</code> 不要求客户端做任何界面动作。</li></ul><h3 id="_205-reset-content" tabindex="-1">205 Reset Content <a class="header-anchor" href="#_205-reset-content" aria-label="Permalink to &quot;205 Reset Content&quot;">​</a></h3><p>成功，且要求客户端<strong>重置</strong>引发该请求的文档视图（如清空表单）。</p><ul><li><strong>MUST NOT</strong> 有消息体（应发 <code>Content-Length: 0</code> 或空 chunked 体）。</li></ul><h3 id="_206-partial-content" tabindex="-1">206 Partial Content <a class="header-anchor" href="#_206-partial-content" aria-label="Permalink to &quot;206 Partial Content&quot;">​</a></h3><p>范围请求成功，体是所请求范围的一部分。</p><ul><li>单范围：<strong>MUST</strong> 带 <code>Content-Range</code>，<code>Content-Length</code> 为该范围长度。</li><li>多范围：体为 <code>multipart/byteranges</code>，<code>Content-Type</code> 指明 boundary，<strong>不带</strong>顶层 <code>Content-Range</code>。</li><li>详见<a href="/Front2Full/manual/computer-programming/http11/range-requests">范围请求</a>。</li></ul><h3 id="_207-208-226" tabindex="-1">207 / 208 / 226 <a class="header-anchor" href="#_207-208-226" aria-label="Permalink to &quot;207 / 208 / 226&quot;">​</a></h3><ul><li><code>207 Multi-Status</code>（RFC 4918）：WebDAV，体为 XML，内含多个独立状态。</li><li><code>208 Already Reported</code>（RFC 5842）：WebDAV 绑定去重。</li><li><code>226 IM Used</code>（RFC 3229）：增量编码，实际几乎无部署。</li></ul><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/status-3xx">状态码：3xx 重定向</a>。</p>',44)])])}const g=o(r,[["render",c]]);export{p as __pageData,g as default};
